-- خزعبلات — 40 مقالًا (مسودّات) من التوليد الآلي.
-- شغّله كاملًا في Supabase → SQL Editor. المقالات تظهر في /admin كمسودّات للمراجعة والنشر.

alter table public.articles add column if not exists tags text[] not null default '{}';

insert into public.articles (slug, title, dek, body, category, level, status, tags) values
  ('blue-eye-bead', 'هل تحميك الخرزة الزرقاء من العين حقاً؟', 'قطعة زجاج زرقاء يعلّقها الناس لردّ الحسد، فهل تحمي فعلاً أم مجرد عادة قديمة؟', 'تتدلّى الخرزة الزرقاء ذات النقطة السوداء في السيارات وعلى صدور الأطفال وفوق أبواب المحلات، ويُقال إنها «تكسر» العين وتردّ نظرة الحاسد قبل أن تصيب. لكن كيف يُفترض أن تعمل قطعة زجاج زرقاء بهذه المهمة الجسيمة؟

أصل هذه الخرزة قديم جداً، ويعود إلى حضارات شرق المتوسط والأناضول حيث عُرفت باسم «نظر بونجوك». اختير اللون الأزرق لأنه كان لون العيون الأقل شيوعاً في تلك المناطق، فارتبط في المخيلة الشعبية بالغرابة والقوة، فصار لوناً «مضاداً» للعين.

من الناحية العلمية لا توجد أي آلية يمكن أن تجعل قطعة زجاج تعترض «طاقة» غير مقيسة وتردّها. لم تُثبت أي تجربة أن وجود الخرزة يغيّر شيئاً في مجريات الحياة، وكل ما يُروى عنها من «نجاح» هو انتقاء للحوادث التي تؤكد الاعتقاد وتجاهل ما لا يؤكده.

أما دينياً فحماية الإنسان تكون بذكر الله والأذكار والرقية المشروعة، وقد نبّه كثير من أهل العلم إلى أن تعليق التمائم والخرز طلباً للحماية أمر منهيّ عنه، لأنه يعلّق القلب بغير الله.

الحكم: العين قد تكون حقيقة يؤمن بها كثيرون، لكن الخرزة الزرقاء ليست درعاً ولا مقياساً؛ هي زينة قديمة اكتست هالة لا يسندها لا علم ولا شرع. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['العين','حسد','تمائم','خرافات']::text[]),
  ('number-13-unlucky', 'لماذا يهرب العالم كلّه من الرقم 13؟', 'فنادق تحذف طابقاً كاملاً وناس يؤجّلون سفرهم، فما جريمة هذا الرقم المسكين؟', 'في كثير من فنادق العالم لن تجد طابقاً يحمل الرقم 13؛ يقفز المصعد من 12 إلى 14 مباشرة. وشركات طيران تتخطى الصفّ رقم 13، وناس يتجنّبون السفر أو الزواج في هذا اليوم. فما سرّ هذا الرقم المسكين؟

للخوف من الرقم 13 اسم علمي هو «تريسكايديكافوبيا». وتتعدّد الروايات حول أصله؛ فبعضها يربطه بالعشاء الأخير حيث كان الحاضرون ثلاثة عشر، وبعضها بأساطير إسكندنافية عن ضيفٍ ثالثَ عشرَ جلب المصيبة. والمهم أن جميع هذه القصص حكايات ثقافية، لا قوانين للكون.

لو كان للرقم أثر حقيقي لظهر في الإحصاءات: معدّلات حوادث أعلى، وخسائر أكثر، ووفيات أكثر في كل ما يحمل الرقم 13. لكن الدراسات التي بحثت هذا لم تجد فرقاً يُذكر. الأرقام محايدة تماماً، والمصادفة وحدها هي التي تجعلنا نتذكّر «اليوم الثالث عشر المشؤوم» وننسى مئات الأيام العادية.

بل إن الطريف أن الأرقام «المنحوسة» تختلف من ثقافة لأخرى؛ فالرقم 4 يُتشاءم منه في شرق آسيا لأن نطقه يشبه كلمة «الموت»، بينما لا يعني شيئاً عندنا. وهذا الاختلاف وحده يكشف أن النحس في العقول لا في الأرقام.

الحكم: الرقم 13 بريء تماماً، ولا يملك من القوة إلا ما نمنحه إياه بأوهامنا. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['أرقام','نحس','تشاؤم']::text[]),
  ('eye-twitch-omen', 'رفّة عينك تبشّرك بخبر... أم مجرّد إرهاق؟', 'يميّز بعضهم بين رفّة العين اليمنى واليسرى، فهل جفنك جهاز إنذار بالغيب؟', '«عيني ترفّ... أكيد في خبر جاي». عبارة نسمعها كثيراً، وبعضهم يفصّل: رفّة العين اليمنى خير، واليسرى شرّ، أو العكس حسب المنطقة. فهل عينك جهاز إنذار مبكّر بالأخبار؟

ما يحدث فعلاً هو تقلّص لا إرادي في عضلات الجفن يُعرف طبياً باسم «الرمع العضلي» أو «الميوكيميا». وهو شائع جداً وغير مؤذٍ في الغالب، وله أسباب واضحة: قلّة النوم، والإرهاق، والتوتّر، والإفراط في القهوة والكافيين، وإجهاد العين من الشاشات، وأحياناً جفاف العين.

لاحظ أن كل هذه الأسباب داخلية تتعلّق بحالة جسدك، لا علاقة لها بأحداث ستقع خارجك. العين لا تعرف الغيب، ولا يوجد أي مسار عصبي يربط رفّة الجفن بزواج قريب أو خبر بعيد.

سبب ثبات هذه الخرافة هو ما يسمّيه علماء النفس «التحيّز التأكيدي»؛ فحين ترفّ عينك ثم يأتي خبر بعد أيام تربط بينهما وتقول «صدقت»، وحين ترفّ ولا يحدث شيء تنسى الأمر تماماً. هكذا تبدو النبوءة ناجحة دائماً في ذاكرة انتقائية.

الحكم: رفّة العين رسالة من جسدك المتعب لا من عالم الغيب؛ نم جيداً وقلّل القهوة تهدأ. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['صحة','العين','تشاؤم']::text[]),
  ('broken-mirror-seven-years', 'المرآة المكسورة وسبع سنوات من النحس: من أين جاءت الحكاية؟', 'كسرت مرآة فارتجفت؟ إليك من أين خرج رقم السبع سنوات تحديداً.', '«من كسر مرآة كُتب عليه سبع سنوات من النحس المتواصل!». جملة تكفي لإصابة أي أحد بالذعر وهو يكنس شظايا المرآة. لكن من أين خرج هذا العدد تحديداً: سبع سنوات؟

يعود أصل هذه الخرافة إلى الرومان القدماء. كانوا يعتقدون أن المرآة تعكس جزءاً من روح الإنسان، وأن الروح تتجدّد كل سبع سنوات. فمن كسر المرآة، بحسب هذا الاعتقاد، «شوّه» انعكاس روحه ووجب أن ينتظر سبع سنوات حتى تتجدّد وتُشفى.

طبعاً لا شيء من هذا يصمد أمام أبسط تفكير. المرآة قطعة زجاج مطليّة بطبقة عاكسة، لا تحتجز أرواحاً ولا تسجّل مصائر. وكسرها حدث فيزيائي بحت، نتيجته الوحيدة الحقيقية هي احتمال أن تجرح يدك إن لم تنظّف الشظايا بعناية.

والمفارقة أن «سبع سنوات» رقم مستوحى من أسطورة عمر الروح، لا من أي رصد واقعي. ولو تتبّعنا حياة كل من كسروا مرايا لما وجدنا نمطاً واحداً من التعاسة يجمعهم.

الحكم: خطر المرآة المكسورة ينحصر في شظاياها الحادّة، لا في سبع سنوات وهمية من الشؤم. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['نحس','أساطير','خرافات']::text[]),
  ('black-cat-bad-luck', 'هل تجلب القطة السوداء سوء الحظ فعلاً؟', 'لون فراءٍ واحد يعني الشؤم هنا والبركة هناك، فأين الحقيقة؟', 'تعبر قطة سوداء الطريق أمام أحدهم فيتوقّف، أو يغيّر مساره، أو يتوقّع يوماً سيئاً. القطة السوداء صارت في مخيّلة كثيرين أيقونةً لسوء الحظ. فما جريمة هذا الحيوان الأسود؟

هذه السمعة السيئة أوروبية المنشأ في الأساس، وتعود إلى العصور الوسطى حين رُبطت القطط السوداء بالسحر والساحرات، فطُوردت وقُتلت في موجات من الخرافة والجهل. ومع الهجرات والقصص انتقلت الفكرة إلى ثقافات أخرى.

الطريف أن الحظ المنسوب للّون نفسه يتناقض بين الشعوب؛ ففي بريطانيا واليابان تُعدّ القطة السوداء جالبةً للحظ الحسن لا السيّئ. فكيف يكون اللون ذاته نحساً هنا وبركةً هناك؟ ببساطة لأن المعنى في ثقافة الناس، لا في فِراء القطة.

علمياً، لون فراء القطة مجرّد صبغة وراثية (الميلانين)، لا تأثير له على مسار حياتك إطلاقاً. القطة السوداء تصطاد الفئران وتموء وتنام مثل أي قطة أخرى تماماً.

الحكم: القطة السوداء ضحية سوء سمعةٍ تاريخي ظالم، لا تجلب حظاً ولا تطرده. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['حيوانات','تشاؤم','خرافات']::text[]),
  ('onion-in-socks', 'بصلة في الجورب تسحب السموم أثناء نومك؟', 'وصفة رائجة تعِد بتنظيف جسمك عبر قدميك ليلاً، فهل للجلد هذا السحر؟', 'تنتشر وصفة «سحرية» على الإنترنت: ضع شريحة بصل في جوربك قبل النوم، وستستيقظ وقد سُحبت السموم من جسمك وتحسّنت صحّتك، بل ويُزعم أنها تعالج الحمّى والرشح. فهل قدمك بوّابة لتنظيف الجسم؟

تقوم الفكرة على وهمٍ مفاده أن باطن القدم يحوي «نقاطاً» متّصلة بالأعضاء، وأن البصل «يسحب» عبرها السموم. والحقيقة أن الجلد حاجز يمنع دخول المواد وخروجها بهذه الطريقة، ولا يعمل كمصفاة تسحب سموماً إلى الخارج.

الأهمّ أن جسم الإنسان يملك أصلاً جهازين متكاملين لتنقية الدم: الكبد والكليتان. هما من يفكّك الفضلات ويطرحها عبر البول والعرق والتنفّس. لا يحتاج جسمك السليم إلى بصلة في الجورب ليتخلّص من «السموم»، والمصطلح نفسه يُستخدم في هذه الوصفات بشكل فضفاض بلا معنى علمي محدّد.

وإن بدا أن أحدهم «تحسّن» بعد التجربة، فذلك لأن نزلات البرد تزول من تلقاء نفسها خلال أيام، فيُنسب الشفاء ظلماً إلى البصلة لا إلى مناعة الجسم ومرور الوقت.

الحكم: البصل لذيذ في الطبق ومفيد في الغذاء، أما في الجورب فلا يسحب سموماً ولا يعالج مرضاً. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['طب شعبي','صحة','وصفات']::text[]),
  ('copper-bracelet-arthritis', 'هل يشفي السوار النحاسي آلام المفاصل؟', 'معدنٌ في المعصم يَعِد بتخفيف الروماتيزم، فماذا قالت التجارب المنضبطة؟', 'يرتدي كثير من كبار السن سواراً نحاسياً في المعصم، مؤمنين أنه يخفّف آلام المفاصل والروماتيزم، ويعتقدون أن النحاس «يتسرّب» عبر الجلد ليعالج الالتهاب. فهل للنحاس هذه المعجزة؟

النحاس عنصر ضروري للجسم بكميات دقيقة جداً، لكننا نحصل عليه من الغذاء لا من ملامسة معدنٍ للجلد. وكمية النحاس التي قد تنتقل من سوار إلى الجسم عبر الجلد ضئيلة إلى حدٍّ لا يكاد يُذكر، ولا علاقة لها بعلاج المفاصل.

وقد اختُبرت هذه الفكرة علمياً؛ ففي دراسة منضبطة قارن باحثون بين مرضى ارتدوا أساور نحاسية وآخرين ارتدوا أساور وهمية، ولم يجدوا فرقاً حقيقياً في الألم بين المجموعتين. أي أن أثر السوار لم يتجاوز أثر «الإيحاء».

وهنا يكمن سرّ استمرار الاعتقاد: مفعول الدواء الوهمي (البلاسيبو). فحين يصدّق المريض أن شيئاً سيخفّف ألمه، قد يشعر فعلاً بتحسّن مؤقّت لأسباب نفسية، فيظنّ أن السوار هو السبب، بينما آلام المفاصل نفسها تشتدّ وتخفّ بطبيعتها بين يوم وآخر.

الحكم: السوار النحاسي حليةٌ جميلة لا دواء؛ ومن يعاني ألم المفاصل فطريقه إلى الطبيب لا إلى المعصم. خزعبلة يشوبها بعض الإيحاء النفسي.', 'myths', 4, 'draft', ARRAY['طب شعبي','مفاصل','صحة']::text[]),
  ('belly-shape-baby-gender', 'شكل بطن الحامل يكشف جنس الجنين... صدفة أم علم؟', '«مدبّبة: ولد، عريضة: بنت»، قاعدةٌ شعبية شهيرة نضعها تحت المجهر.', '«بطنها مدبّبة إلى الأمام: ولد. بطنها عريضة ومنتشرة: بنت». يجزم كثيرون بمعرفة جنس الجنين من شكل بطن الأم قبل السونار. فهل في هذا ذرّة من علم؟

جنس الجنين يتحدّد لحظة الإخصاب عبر الكروموسومات، ذكراً كان أو أنثى، ولا يترك هذا التحديد أثراً على الشكل الخارجي لبطن الأم. أما شكل البطن فتحكمه عوامل أخرى تماماً: قوّة عضلات البطن، وبنية جسم الأم، ووضعية الجنين، وعدد مرّات الحمل السابقة.

لهذا تختلف بطون الأمّهات وهنّ يحملن الجنس نفسه؛ فقد تكون بطن حاملٍ بولدٍ عريضةً، وأخرى حاملٍ ببنتٍ مدبّبة، بلا قاعدة ثابتة. وأي «توقّع» من شكل البطن هو في جوهره تخمين احتماله الصحيح خمسون بالمئة، تماماً كرمي قطعة نقود.

هذه النسبة العالية للصدفة هي ما يبقي الخرافة حيّة؛ فحين تصيب الجدّة في توقّعها يتناقل الجميع فراستها، وحين تخطئ يُنسى الأمر بلطف. النصف الناجح وحده هو ما يُروى.

الحكم: شكل بطن الحامل لا يفشي سرّ الجنين؛ والوسيلة الموثوقة هي السونار لا فراسة العين. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['حمل','أمومة','خرافات']::text[]),
  ('upside-down-shoe', 'الحذاء المقلوب يجرّ الشؤم إلى البيت؟', 'يدٌ تسارع لتعديل الحذاء المنقلب خشية النحس، فهل لوضعيته أثرٌ في الحظ؟', 'في كثير من البيوت العربية، ما إن يُرى حذاءٌ منقلبٌ وباطنه إلى الأعلى حتى تسارع يدٌ إلى تعديله، خشية أن يجلب هذا الوضع الشؤم أو الخصام أو غضب السماء. فهل لوضعية الحذاء أثرٌ في حظّ أهل البيت؟

هذا الاعتقاد في جوهره مسألة آدابٍ وذوقٍ اجتماعي تحوّلت مع الوقت إلى «نحس». ففي ثقافات عديدة يُعدّ توجيه باطن الحذاء نحو الأعلى أو نحو الناس قلّة احترام، فرُبط الأمر تدريجياً بجلب سوء الحظ ليكتسب قوّة الردع.

من حيث السبب والنتيجة لا يوجد أي رابط. انقلاب الحذاء حدثٌ فيزيائي عابر لا يرسل إشارات إلى الكون ولا يغيّر رزق أحدٍ أو صحّته. ولو صوّرنا آلاف البيوت التي ينقلب فيها حذاء يومياً لما وجدنا موجة مصائب تعقب ذلك.

تعديل الحذاء بدافع النظافة والذوق أمرٌ جميل، أما فعله خوفاً من عقابٍ غيبي فهو تحميلٌ لقطعة جلدٍ ما لا تحتمله، وتعليقٌ للقلب بأوهامٍ لا أساس لها.

الحكم: اعدل حذاءك من باب الترتيب والذوق، لا خوفاً من شؤمٍ لا وجود له. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['عادات','تشاؤم','خرافات']::text[]),
  ('ringing-ears-someone-talking', 'طنين أذنك يعني أن أحدهم يتحدّث عنك؟', 'أزيزٌ مفاجئ في الأذن يُفسَّر بحديث الغائبين عنك، فما مصدره الحقيقي؟', 'يرنّ في أذنك طنينٌ مفاجئ، فيبتسم من حولك: «أكيد أحدهم يذكرك الآن»، وبعضهم يميّز الأذن اليمنى بالمدح واليسرى بالذمّ. فهل أذنك جهاز التقاطٍ لأحاديث الناس عنك؟

ما تسمعه يُعرف طبياً باسم «الطنين»، وهو إحساس بصوت رنينٍ أو أزيزٍ لا مصدر خارجي له. وله أسباب معروفة ومدروسة: التعرّض للأصوات العالية، وتراكم الصملاخ (شمع الأذن)، والتغيّرات المرتبطة بالتقدّم في العمر، وبعض الأدوية، وأحياناً ارتفاع ضغط الدم.

كل هذه أسباب داخل أذنك وجسمك، لا علاقة لها بشخصٍ يجلس في مدينة أخرى يتحدّث عنك. لا يوجد أي مسارٍ معروف تنتقل عبره كلمات الناس لتُحدث رنيناً في أذنٍ بعينها؛ الأمر ببساطة خارج قوانين الفيزياء والأحياء.

أما لماذا تصدّق هذه الخرافة، فلأن الطنين شائعٌ ويتكرّر، فيسهل أن تربطه بأي حديثٍ تسمعه لاحقاً وتقول «صدق الطنين». ولو كان الطنين مستمراً أو مؤلماً أو مصحوباً بضعف سمع، فالأولى مراجعة الطبيب لا البحث عمّن يذكرك.

الحكم: طنين أذنك خبرٌ عن صحّتك أنت، لا عن ألسنة الناس؛ وإن تكرّر فاستشر طبيباً. خزعبلة كبرى.', 'myths', 5, 'draft', ARRAY['صحة','الأذن','خرافات']::text[]),
  ('umm-al-duwais', 'أم الدويس: جميلة برائحة عطر... ويدان كالمنجل؟', 'امرأة فاتنة تفوح بالعطر تصطاد الرجال في الظلام... فما أصل الحكاية؟', 'الحكاية كما تُروى في مجالس الإمارات ودول الخليج: في جوف الليل تظهر امرأة فائقة الجمال، تفوح منها رائحة عطر أخّاذة، تستدرج الرجل الذي تُسوّل له نفسه اللحاق بها. وحين يقترب يكتشف أن يديها شفرتان حادّتان كالمنجل، وأن وجهها الفاتن يخفي وحشًا.

تتكرّر التفاصيل في كل رواية تقريبًا: العطر، الجمال الليلي، السلاح المخبّأ، والضحية دائمًا رجل يبحث عن مغامرة عابرة. هذا الثبات في العناصر ليس مصادفة؛ فالحكاية مبنية لتؤدّي وظيفة اجتماعية واضحة.

يرى كثير من الدارسين للفلكلور الشعبي أن أم الدويس أشبه بـ«حارسة أخلاق» غير رسمية: تخويف الرجال من الخيانة ومن التسكّع ليلًا وراء نساء غريبات. فالعقاب في القصة يقع حصرًا على من تقوده شهوته إلى الظلام، وهي رسالة تربوية في لبوس مرعب.

انتقلت الحكاية شفويًا بين الأجيال في سهرات السمر، ثم وجدت حياة ثانية على منصات مثل يوتيوب وتيك توك، حيث أعاد صنّاع المحتوى إنتاجها كقصص رعب مصوّرة، فتجدّد انتشارها بين جيل لم يسمعها من جدّاته.

الحكم: أم الدويس أسطورة شعبية لا سند لها في الواقع، لكنها ليست مجرد حكاية رعب؛ إنها أداة تهذيب اجتماعي صاغها المجتمع ليكبح سلوكًا بعينه. خزعبلة كحقيقة، بارعة كرسالة.', 'legends', 3, 'draft', ARRAY['أساطير خليجية','أم الدويس','فلكلور شعبي']::text[]),
  ('al-saalwa', 'السعلوة: هل تتنكّر الغولة في ثوب امرأة؟', 'كائن يغيّر شكله ويسكن الخرائب... حكاية السعلوة بين الرعب والرمز.', 'الحكاية: السعلوة (وتُلفظ أحيانًا السِّلعوة) كائن مؤنّث مخيف، يوصف بأنه غولة قادرة على تغيير هيئتها، تسكن الخرائب والوديان والأماكن المهجورة، وقد تتنكّر في صورة امرأة عجوز أو حتى في هيئة قريبة للضحية لتخدعه.

جذور الاسم ضاربة في العربية القديمة؛ فـ«السِّعلاة» وردت في المعاجم وكتب التراث بوصفها أنثى الغيلان، وذكرها العرب في أشعارهم وأمثالهم القديمة. أي أن السعلوة الخليجية امتداد لمخيّلة عربية أقدم بكثير من الخليج المعاصر.

وظيفتها في الحكاية الشعبية مزدوجة: تخويف الأطفال من الخروج ليلًا أو التسكّع في الأماكن المقفرة، وتفسير ما كان يصعب تفسيره من أصوات الليل ووحشة الخراب. فحين يعجز الناس عن تعليل صوت غريب في العتمة، يملأ الخيال الفراغ بكائن له اسم وملامح.

الحكم: السعلوة شخصية أسطورية عريقة في التراث العربي، مفيدة لفهم كيف صاغت مخيّلة الأجداد مخاوفهم من المجهول. أما وجودها الفعلي فخزعبلة من الطراز الأوسط: حكاية جميلة، وحقيقة معدومة.', 'legends', 3, 'draft', ARRAY['غيلان','تراث عربي','السعلوة']::text[]),
  ('bu-darya', 'بو درية: عريس البحر الذي أرعب غوّاصي اللؤلؤ', 'عريس البحر الذي أرعب غوّاصي اللؤلؤ... حقيقة أم رهبة من الأعماق؟', 'الحكاية: بو درية (أبو دريّة، المنسوب إلى البحر) كائن بحري في فلكلور الخليج، يُقال إنه يظهر للغوّاصين والبحّارة في عرض الماء، نصفه إنسان ونصفه مخلوق بحري، وقد يقلب السفن أو يستدرج الغافلين إلى الأعماق.

عاش أهل الخليج قرونًا على الغوص وصيد اللؤلؤ، وكانت رحلات الغوص طويلة ومحفوفة بمخاطر حقيقية: العواصف، القروش، ضيق النفس، والغرق. في هذا العالم القاسي وُلدت حكايات كائنات البحر لتضع وجهًا مألوفًا على خطرٍ مجهول لا وجه له.

بو درية إذًا تجسيد لرهبة البحر نفسه. فالبحّار الذي يقضي أسابيع فوق الماء تحت رحمة الطبيعة يحتاج إلى سردية تفسّر الأهوال وتحذّر المبتدئين من الاستهانة بالأعماق، والكائن الخرافي يؤدّي هذه المهمة ببراعة.

الحكم: بو درية مخلوق لا وجود له، لكنه مرآة صادقة لعلاقة أهل الخليج بالبحر: رزق ورهبة في آنٍ واحد. خزعبلة بحرية بامتياز، لكنها تحمل في طيّاتها تاريخًا حقيقيًا من المخاطر والشجاعة.', 'legends', 3, 'draft', ARRAY['أساطير البحر','الخليج','الغوص واللؤلؤ']::text[]),
  ('bu-lahyaf', 'بو لهيف: فزّاعة البحر التي حمت الأطفال من الغرق', 'بعبع يخطف من يقترب من الماء... خرافة صُنعت لتنقذ الأطفال من الغرق.', 'الحكاية: في السواحل الخليجية كان الكبار يحذّرون الصغار من «بو لهيف»، كائن يترصّد الأطفال الذين يقتربون من البحر وحدهم فيخطفهم إلى الماء. ومجرد ذكر اسمه كان كفيلًا بأن يُجمّد طفلًا في مكانه بعيدًا عن الشاطئ.

خلف هذا الرعب تكمن حكمة عملية: البحر مصدر رزق أهل الخليج، لكنه أيضًا خطر مميت على طفل صغير يسبح بلا رقيب. لم تكن هناك حواجز أمان ولا منقذون، فكان الخوف من «بو لهيف» هو حاجز الأمان الوحيد المتاح.

هذا النمط من «الوحوش الحارسة» عالمي؛ فلكل ثقافة بعبعها الذي يُبعد الأطفال عن الخطر: البئر، أو النهر، أو الغابة، أو البحر. والقاسم المشترك أن الكائن المخيف يحلّ محلّ شرحٍ منطقي يصعب على الطفل استيعابه أو تصديقه.

الحكم: بو لهيف لا يسبح في أي بحر إلا بحر الخيال، لكنه ربما أنقذ أطفالًا حقيقيين من الغرق. خزعبلة في جوهرها، ذكية في غايتها.', 'legends', 3, 'draft', ARRAY['بعابع الأطفال','البحر','تراث خليجي']::text[]),
  ('tantal', 'طنطل: العملاق الذي يطول ويقصر في عتمة الليل', 'عملاق ليليّ يطول ويقصر ليضلّل السائرين... كيف وُلدت حكاية طنطل؟', 'الحكاية: طنطل كائن ليليّ يتردّد ذكره في التراث العراقي وبعض مناطق الخليج، يوصف بأنه شبح طويل يظهر للسائرين وحدهم في العتمة، يتلاعب بحجمه وشكله فيطول حتى يكاد يبلغ السماء أو ينكمش، ليضلّل ضحيته ويبثّ فيها الرعب.

كغيره من كائنات الليل، يزدهر طنطل حيث تنعدم الإضاءة وتكثر الوحشة. فقبل الكهرباء كان الليل عالمًا مجهولًا مرعبًا، والظلال تلعب بالأبصار، فيسهل أن يتحوّل جذع شجرة أو ظلّ جدار إلى «عملاق» في مخيّلة رجل خائف يسير وحده.

ووظيفة الحكاية تحذيرية بالدرجة الأولى: لا تتجوّل وحدك في الظلام. وهي نصيحة كانت في زمنها منطقية تمامًا، إذ يخفي الليل مخاطر واقعية من حيوان مفترس أو لصّ أو تيهٍ في الطريق.

الحكم: طنطل ابن الظلام والخيال، يتلاشى فور أن يُضاء المكان. خزعبلة تراثية طريفة، لكن تحذيرها من متاهات الليل لم يكن بلا معنى في زمنٍ بلا مصابيح.', 'legends', 3, 'draft', ARRAY['أساطير الليل','تراث عراقي','طنطل']::text[]),
  ('hmarat-al-gaila', 'حمارة القايلة: لماذا مُنعنا من اللعب وقت الظهيرة؟', 'كائن يظهر عند حرّ الظهيرة ليخطف الأطفال... ما سرّ توقيته؟', 'الحكاية: «حمارة القايلة» كائن يُقال إنه يظهر في وقت القيلولة، أي ذروة حرّ الظهيرة صيفًا، ليخطف الأطفال الذين يلعبون في الأزقّة بدل أن يناموا. ويوصف أحيانًا على هيئة حمار أو امرأة، ويرتبط اسمه بوقت «القايلة» على وجه التحديد.

هنا تتجلّى الحكمة المناخية: في صيف الجزيرة العربية والخليج تكون الظهيرة قاتلة الحرارة، والخروج فيها يعرّض الطفل لضربة شمس أو جفاف. فكانت «حمارة القايلة» وسيلة لإجبار الصغار على النوم أو البقاء في الظلّ خلال أخطر ساعات النهار.

واللافت أن التوقيت جزء من الأسطورة نفسها؛ فالكائن لا يظهر ليلًا كغيره من الوحوش، بل في وضح النهار عند اشتداد الحرّ، وهو ما يربط الخرافة مباشرة بالخطر الحقيقي الذي صُمّمت لتجنّبه.

الحكم: لا حمار ولا غولة تجوب الأزقّة عند الظهر، لكن ضربة الشمس حقيقية جدًا. خزعبلة في القالب، نصيحة صحية في المضمون.', 'legends', 3, 'draft', ARRAY['أساطير خليجية','الظهيرة','بعابع الأطفال']::text[]),
  ('al-naddaha', 'النداهة: حين ينادونك باسمك عند النهر فلا تلتفت', 'صوت أنثوي يناديك باسمك قرب النهر ليلًا... فهل تتبعه؟', 'الحكاية: النداهة أسطورة ريفية مصرية شهيرة عن امرأة فاتنة تظهر قرب النهر أو الحقول ليلًا، تنادي الرجل باسمه بصوت عذب لا يُقاوَم، فمن يستجيب لها ويتبعها يختفي في الماء ولا يعود. واسمها من الفعل «ندَه» أي نادى.

يرى دارسو الفلكلور أن النداهة تجسيد للنهر نفسه بإغرائه وخطره؛ فالنيل مصدر الحياة، لكنه أيضًا يبتلع من يقترب منه ليلًا بلا حذر. وتحويل الغرق المفاجئ إلى «نداء ساحر» يمنح الموت المباغت تفسيرًا وقصة يطمئنّ إليها الناس.

وللحكاية بُعد اجتماعي أيضًا: تحذير الرجال من اتّباع إغراء مجهول ليلًا، وترسيخ فكرة أن الاستجابة للمغريات العابرة تقود إلى الهلاك. وقد ألهمت النداهة الأدب والسينما المصرية، فخرجت من حكايات القرى إلى الشاشة الكبيرة.

الحكم: النداهة صوت لا مصدر له إلا الخيال، لكنها تختصر علاقة الإنسان بالنهر: جمال قاتل. خزعبلة، نعم، لكنها من أجمل ما نسجه الوجدان الشعبي.', 'legends', 3, 'draft', ARRAY['فلكلور مصري','النداهة','أساطير الأنهار']::text[]),
  ('umm-al-saaf', 'أم السعف والليف: جنّية النخيل التي تخيف الصغار', 'جنّية يكسوها السعف وينسدل شعرها كالليف... لماذا تخيف الأطفال؟', 'الحكاية: «أم السعف والليف» شخصية مخيفة في فلكلور الجزيرة العربية والخليج، امرأة أو جنّية ينسدل شعرها كليف النخيل ويكسو جسدها السعف، تظهر للأطفال لتخيفهم إن أساؤوا التصرّف أو خرجوا وقت المغرب.

يرتبط اسمها ومظهرها بالنخلة، عماد الحياة في بيئة الواحات والصحراء. فالخيال الشعبي يستعير عناصر البيئة المحيطة — السعف والليف — ليصوغ منها كائنًا مألوفًا وغريبًا في آنٍ واحد، أقرب إلى نفوس الأطفال وأشدّ وقعًا عليهم.

وكسائر «بعابع» الأطفال، وظيفتها ضبط السلوك: النوم مبكرًا، وعدم الخروج عند الغروب (وهو وقت كان يُعدّ خطِرًا في المعتقد الشعبي)، وطاعة الكبار. فالكائن هنا أداة تربية أكثر منه مخلوقًا مرعبًا.

الحكم: أم السعف والليف لا تسكن أي نخلة إلا نخلة الخيال، لكنها نموذج بديع لكيف تحوّل الثقافة بيئتها إلى حكايات. خزعبلة تربوية بنكهة النخيل.', 'legends', 3, 'draft', ARRAY['بعابع الأطفال','تراث خليجي','النخيل']::text[]),
  ('mermaid-arab', 'عروس البحر: نصفها إنسان ونصفها سمكة... من أين جاءت؟', 'نصفها امرأة ونصفها سمكة، وتظهر في كل الثقافات... فمن أين جاءت؟', 'الحكاية: عروس البحر (أو حورية البحر) كائن أنثوي نصفه العلوي امرأة ونصفه السفلي ذيل سمكة، يظهر في أساطير شعوب لا تُحصى حول العالم، من بلاد الرافدين القديمة إلى الإغريق وأوروبا وسواحل العرب. صوتها الساحر يستدرج البحّارة، وجمالها يفتنهم.

الغريب أن الأسطورة نفسها تكرّرت في ثقافات لم تتلاقَ، ما يشير إلى منبع نفسي مشترك: افتتان الإنسان بالبحر ورهبته منه. ويربط بعض الباحثين بين مشاهدات «الحوريات» وحيوانات بحرية حقيقية كخِراف البحر (الأطوم/الدوغونغ) التي قد تبدو من بعيد وفي ضوء خافت شبيهة بكائن نصف بشري.

وفي التراث العربي وردت إشارات إلى «إنسان الماء» وعجائب البحار في كتب مثل حكايات ألف ليلة وليلة وأدب الرحلات، حيث امتزج الواقع بالخيال في وصف مخلوقات الأعماق. فالبحر المجهول كان مصنعًا لا ينضب للأساطير.

الحكم: لا دليل علمي على وجود عرائس البحر، والأرجح أن أصلها مزيج من مشاهدات مضلِّلة وخيال خصب. خزعبلة كبرى بمقاييس العلم، لكنها من أعرق أساطير البشرية وأكثرها فتنة.', 'legends', 4, 'draft', ARRAY['حورية البحر','أساطير عالمية','البحر']::text[]),
  ('abu-regl-maslukha', 'أبو رجل مسلوخة: بعبع الأطفال ذو الساق المكشوطة', 'رجل بساق مسلوخة يخطف الأطفال العصاة... بعبع صُنع للترهيب.', 'الحكاية: «أبو رجل مسلوخة» من أشهر بعابع الأطفال في مصر وبعض بلاد الشام، رجل مخيف إحدى ساقيه مسلوخة أي منزوعة الجلد، يخطف الأطفال العصاة أو من يخرجون وحدهم إلى الشارع ليلًا. واسمه وحده كان كافيًا لإسكات طفل مشاغب.

ومثل كل البعابع، لا وصف ثابت له؛ فكل جدّة تضيف تفصيلًا أكثر رعبًا من سابقتها. والغاية واحدة: ردع الأطفال عن سلوك خطر أو مزعج — التسكّع ليلًا، أو فتح الباب للغرباء، أو العصيان — عبر خلق تهديد ملموس يفهمه الطفل ويخافه.

ويكشف هذا النوع من الحكايات عن أسلوب تربوي قديم يعتمد الترهيب بدل الشرح، وهو أسلوب تراجع اليوم مع تغيّر مفاهيم التربية، لكنه ترك بصمته في ذاكرة أجيال كاملة كبرت على الخوف من كائنات لا وجود لها.

الحكم: أبو رجل مسلوخة محض اختراع لترويض الصغار، وقد أدّى مهمته لأجيال. خزعبلة تربوية قديمة، الأفضل أن تبقى في الماضي حيث تنتمي.', 'legends', 3, 'draft', ARRAY['بعابع الأطفال','فلكلور مصري','التربية بالترهيب']::text[]),
  ('whatsapp-family-hospital', 'هل صارت مجموعة العائلة أكبر مستشفى في العالم؟', 'كل عمّ وخالة صار استشاريًا، والوصفة تنتقل أسرع من العدوى نفسها', 'تبدأ القصة برسالة بريئة في مجموعة العائلة: «انتبهوا! هذا المشروب يذيب الدهون وينظّف الكبد ويحسّن المزاج ويصلح كذلك خلافات الجيران». لا اسم طبيب، لا مصدر، لا حتى علامة ترقيم، لكنها تنتشر خلال دقائق وكأنها فتحٌ علمي مبين.

في هذه المستشفى الافتراضية، كل فرد قسم مستقل: العمّة رئيسة قسم الأعشاب، والخال استشاري الوصفات المنقولة، وابن العم أخصائي «صديقي جرّبها وشُفي تمامًا». أما التشخيص فيصل قبل أن تُكمل جملتك: تشكو من صداع بسيط، فيخرج عليك ثلاثة تحاليل ومسحة على الريق ووصية بالابتعاد عن «الأبراج الكهربائية».

الطريف أن الوصفة الواحدة تعالج كل شيء: الليمون للبرد، ونفس الليمون للضغط، ونفس الليمون للكآبة، ونفس الليمون لتلميع الأواني. ومع كل إعادة إرسال تكبر الأرقام: كانت ملعقة، فصارت كوبًا، فصارت «لترًا يوميًا على الريق حتى الشفاء».

ولأن أحدًا لا يقرأ حتى النهاية، تُدفن في آخر الرسالة جملة صغيرة: «استشر طبيبك». وهي الجملة الوحيدة الصحيحة، وللأسف هي أكثر جملة يتخطّاها القرّاء.

الحكم: هذا المقال هزلٌ محض للترفيه. مجموعة العائلة مكان جميل للمحبة والصور والدعوات، لا للتشخيص والوصفات. أي شكوى صحية حقيقية طريقها الطبيب المختص، لا زر «إعادة توجيه». مقياس الخزعبلة هنا: 5 من 5.', 'satire', 5, 'draft', ARRAY['واتساب','طب شعبي','سخرية']::text[]),
  ('instant-expert-phenomenon', 'الخبير الذي لم يدرس شيئًا… ويعرف كل شيء', 'بين مقطعٍ قصير وعنوانٍ صادم، وُلد خبيرٌ جديد يفتي في كل العلوم دفعة واحدة', 'هناك كائن عجيب يظهر في كل مجلس: قرأ عنوان مقال، وشاهد نصف مقطع، ثم تحوّل بقدرة قادر إلى مرجعٍ في الاقتصاد والطب والفلك والتغذية والسياسة الدولية، وكل ذلك قبل أن يبرد فنجان القهوة.

لغته سرّية لكنها مقنعة: يبدأ بعبارة «ثبت علميًا» من غير أن يذكر أين ثبت ولا من أثبته، ويختم بـ«لكن لا يريدونك أن تعرف»، وهي جملة سحرية تحوّل أي كلام عادي إلى سرٍّ خطير تخفيه جهات غامضة.

إن سألته عن المصدر أصابك بنظرة شفقة وقال: «افتح عينك وابحث بنفسك». وحين تبحث فعلًا ولا تجد شيئًا، يكون قد انتقل إلى موضوع آخر يفتي فيه بنفس الثقة الفولاذية.

وأجمل ما في الخبير الوهمي أنه لا يخطئ أبدًا؛ فإن صحّ كلامه قال «أنا قلت لكم»، وإن بطل قال «انتظروا وستفهمون لاحقًا». إنه في مأمنٍ دائم من مقصلة الأدلة.

الحكم: مكتوب بروح ساخرة للتسلية. الثقة ليست دليلًا، والعنوان ليس بحثًا. الخبرة الحقيقية تُعرف بالسؤال البسيط: «ما مصدرك؟» ومن يهرب من هذا السؤال، هرب من الحقيقة. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['خبراء وهميون','سخرية','إشاعات']::text[]),
  ('couch-football-analyst', 'محلّل كرة القدم على الكنبة: عبقري لم تكتشفه الأندية بعد', 'من على الأريكة يدير المباراة والفريق والاتحاد الدولي بريموت واحد', 'في الدقيقة الأولى من المباراة يكون قد شكّل التشكيلة، وأقال المدرّب، وباع لاعبين، وحدّد المصير النهائي للبطولة. سلاحه الوحيد: كيس مكسّرات، وريموت، وثقةٌ لا تتزعزع بأنه أذكى من أربعة وعشرين ناديًا محترفًا مجتمعة.

قوانينه في التحليل بسيطة وثابتة: إذا فاز الفريق فالفضل لفراسته هو، وإذا خسر فالسبب مؤامرة من الحكم والكرة والأرضية والطقس وربما دوران الأرض. أما الحلول فجاهزة دائمًا: «كان لازم يمرّرها»، تُقال بعد أن يكون اللاعب قد مرّرها بالفعل وضاعت الفرصة.

ولديه علمٌ خفيّ لا يملكه أحد: يعرف نيّة اللاعب من نظرته، ويقرأ خطط المدرّب من طريقة وقوفه، ويتوقّع النتيجة قبل صافرة البداية… ثم يعدّل توقّعه بعد صافرة النهاية ليصبح صحيحًا مئة بالمئة.

وحين ينتهي كل شيء، يلتفت إلى الحاضرين بجملته الخالدة: «قلتلكم من البداية»، رغم أنه في البداية كان قال العكس تمامًا، لكن الذاكرة الجماعية للأريكة قصيرة ورحيمة.

الحكم: نكتة محبّبة لكل عاشق للكرة. التحليل هواية جميلة ما دام يبقى في حدود المرح، والاختلاف على النتيجة أطرف من الاتفاق عليها. المهم ألا نأخذ فتاوى الأريكة على محمل الجد. مقياس الخزعبلة: 4 من 5.', 'satire', 4, 'draft', ARRAY['كرة القدم','سخرية','تحليل']::text[]),
  ('lemon-cures-everything', 'الليمون على الريق: الدواء الذي يعالج حتى ما لا مرض له', 'من نزلات البرد إلى مشاكل الشركات، حبّة ليمون واحدة تحلّ الكون', 'لكل بيتٍ عربي بطلٌ خارق اسمه الليمون. تشكو من زكام؟ ليمون. ضغطك مرتفع؟ ليمون. تريد إنقاص وزنك؟ ليمون على الريق. مللت من الحياة؟ ليمون، لكن مع نعناع هذه المرة لتغيير الأجواء.

مع كل جيلٍ تكبر الأسطورة: كان يُستعمل في الطبخ، فصار يُشرب صباحًا، ثم قيل إنه «يذيب الدهون»، ثم «ينظّف الدم»، ثم «يطرد السموم»، وهي عبارات فخمة لا يعرف قائلها أي سمٍّ يقصد ولا من أين يخرج.

طبعًا الليمون فاكهة لطيفة وفيها فيتامين مفيد وطعمها منعش، وهذا شيءٌ جميل حقيقي. لكن المشكلة تبدأ حين نحمّل الحبّة المسكينة مسؤولية علاج أمراضٍ مزمنة، ونترك الطبيب والدواء انتظارًا لمفعولها السحري الذي لن يأتي.

وكلما اعترض أحدهم علميًا، جاء الرد الحاسم: «جدّي عاش تسعين سنة وكان يشربه». وهو دليلٌ عاطفي جميل، لكنه لا يفرّق بين مصادفة سعيدة وقانونٍ طبي.

الحكم: مكتوب على سبيل المزاح المحبّب. الليمون غذاء طيّب لا دواء معجزة، ولا بأس بكوبٍ منه لأنه لذيذ، لا لأنه سيشفي كل داء. المرض الحقيقي طبيبه الطبيب، لا عصير الفاكهة. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['طب شعبي','مبالغات','سخرية']::text[]),
  ('who-started-the-rumor', 'من أطلق هذه الإشاعة؟ لا أحد… والجميع صدّقها', 'خبرٌ بلا مصدر يجوب المدينة كلها بينما صاحبه الأصلي غير موجود', 'للإشاعة سيرة ذاتية مثيرة: تولد فجأة بلا أب معروف، وتكبر بسرعة خرافية، وتسافر بين المجالس والمجموعات، وحين تسأل أول شخص عن مصدرها يقول لك بثقة: «سمعتها من ناس»، وهؤلاء «الناس» هم أكبر وكالة أنباء في التاريخ ولا يعرف أحد عنوانها.

تقنيتها بسيطة: تبدأ صغيرة «يقولون إن…»، ثم تتضخّم مع كل رواية. فما كان «قد» يصبح «أكيد»، و«ربما» تصير «رسميًا»، وشخصٌ مجهول يتحوّل إلى «مصدر مطّلع» بلا اسم ولا وجه ولا وظيفة.

وأطرف مراحلها حين تعود الإشاعة إلى الشخص نفسه الذي أطلقها من غير قصد، فيصدّقها هذه المرة ويقول: «شفتوا؟ أنا كنت أحسّ فيها»، ناسيًا أنه هو من نفخ فيها الروح قبل أسبوع.

ولها قانونٌ ذهبي: التصحيح لا يصل أبدًا بنفس سرعة الإشاعة. تنتشر الكذبة في دقائق، بينما يبقى التوضيح واقفًا في الطابور ينتظر من يقرأه.

الحكم: كُتب بأسلوبٍ فكاهي للتذكير لا للتخويف. سؤال واحد يكفي لقتل معظم الإشاعات: «منين هالخبر؟». فإن لم يكن له مصدر واضح، فالأفضل أن يموت عندك لا أن يكبر بك. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['إشاعات','سخرية','مصداقية']::text[]),
  ('seven-minute-voice-note', 'الرسالة الصوتية أبو سبع دقائق: ملحمة لا يعرف أحد نهايتها', 'يبدأ بالسلام ويمرّ بالطقس والجيران قبل أن يصل إلى الجملة الوحيدة المهمة', 'تصلك رسالة صوتية طولها سبع دقائق، فتشعر أنها دعوة لحضور مؤتمر لا لسماع خبر. تضغط تشغيل بقلبٍ مرتجف، فتبدأ الملحمة: سلامٌ طويل، وسؤال عن الأحوال، وتعليق على الطقس، وحكاية جانبية عن ابن الجيران، وكل هذا قبل الوصول إلى المعلومة الفعلية المخبّأة في الثانية الأخيرة.

ومن قوانين الرسالة الصوتية الكونية أن المعلومة المهمة توجد دائمًا في آخر عشر ثوانٍ، بينما الست دقائق والنصف الأولى مقدّمة تمهيدية لا يفهمها إلا صاحبها. وحين تسرّع التشغيل يتحوّل الصوت إلى كائن فضائي، لكنك تفضّل الفضائيين على انتظار كل هذا الوقت.

ثم تأتي الطامة: تصلك بعدها رسالة صوتية ثانية طولها خمس دقائق تبدأ بـ«نسيت أقولك»، وكأن الملحمة الأولى كانت مجرد مقدمة للجزء الثاني من المسلسل.

ولو طلبت بأدب: «ممكن تكتبها؟»، تُتّهم فورًا بالكسل، رغم أن كتابة سطرين أرحم للطرفين من إنتاج فيلمٍ صوتيّ كامل بلا سيناريو.

الحكم: هزلٌ خالص للضحك. الرسالة الصوتية نعمة للمشاعر، لكنها ليست مكانًا للأخبار العاجلة التي تُقرأ في ثانية. رحم الله من أوصل مقصده باختصار، وأراح مستمعيه من الملاحم. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['واتساب','سخرية','عادات']::text[]),
  ('know-it-all-relative', 'قريبك الذي يعرف كل شيء: موسوعة تمشي على قدمين', 'في كل عائلة مرجعٌ واحد يفتي في الطب والسيارات والزواج والاقتصاد دفعة واحدة', 'في كل عائلة قريبٌ يملك إجابة جاهزة عن كل سؤال في الكون قبل أن تكمل السؤال. اشتريت سيارة؟ «غلط، كان لازم الثانية». تخصصك الجامعي؟ «ما له مستقبل». طبخة العشاء؟ «الملح زايد، أنا خبير».

لا موضوع يخرج عن اختصاصه، لأنه ببساطة يختص في كل شيء: هندسة، وطب، وأرصاد، وتربية أطفال لم ينجب منهم واحدًا، ونصائح زواجٍ يقدّمها بثقةٍ عجيبة رغم أنه لم يجرّبه، أو جرّبه ولم ينجح، وهذا لا يقلّل من ثقته أبدًا.

سلاحه الأقوى عبارتان: «أنا أدرى» و«اسمع كلامي وبتشوف». وإن أثبتّ له العكس بالدليل، ابتسم ابتسامة الحكيم وقال: «كل واحد وله رأيه»، بعد أن كان قبل دقيقة يرفض أن يكون لأحد رأي غير رأيه.

ومع ذلك، نحبّه؛ فهو جزءٌ من نكهة المجلس، ولولا نصائحه المجانية غير المطلوبة لفقدت اللمّة نصف طرافتها.

الحكم: مكتوب بمودّة وسخرية لطيفة. النصيحة هدية، لكن الهدية غير المطلوبة تُوضع بأدب على الرف. خذ من كلامه ما يفيد، وابتسم لما يزيد، ولا تبنِ قرارك على ثقة قريبٍ لا يعرف حدود معرفته. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['خبراء وهميون','سخرية','عائلة']::text[]),
  ('folk-weather-forecast', 'توقّعات الطقس عند الحاج فلان: ركبتُه أدقّ من الأقمار الصناعية', 'حين تتألم ركبته يعلن هطول المطر، وإذا أخطأ فالسماء هي المخطئة', 'بينما تكدح الأقمار الصناعية وأجهزة الرصد لتوقّع الطقس، يجلس الحاج فلان مطمئنًا لأن لديه جهازًا لا يُعطب: ركبته. تؤلمه فيقول «الليلة مطر»، وتخفّ فيقول «الجو رايق»، وكل ذلك بثقة مؤسسة أرصادٍ كاملة.

علمه لا يقتصر على الركبة، بل يشمل لون الغيوم، وطيران الطيور، وحركة النمل، وطعم الهواء. يجمع هذه «البيانات» بحاسّته الخاصة، ثم يصدر نشرته الجوية على فنجان القهوة بثقةٍ لا تعرفها القنوات الرسمية.

وأجمل ما فيه أنه لا يُخطئ أبدًا في نظره: إن نزل المطر فهو عبقري، وإن لم ينزل قال «تأخّر بس جاي»، فيبقى توقّعه صحيحًا إلى أجلٍ غير مسمّى، وهي أذكى طريقة للنجاة من الخطأ.

الحقيقة أن كبار السن يملكون خبرة جميلة في قراءة علامات الطبيعة تستحق الاحترام، لكن الفارق أن الخبرة تقدير محبّب، أما توقّع الطقس الدقيق فيحتاج أجهزة لا ركبًا.

الحكم: كُتب على سبيل الدعابة المحبّة لكبارنا. حكمة الأجداد كنز، لكن لتنظيم رحلةٍ أو سفرة، النشرة الرسمية أضمن من مفاصل الحاج فلان مهما كانت صادقة. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['مبالغات','سخرية','طقس']::text[]),
  ('forward-to-ten-or-else', '«انسخ وأرسل لعشرة وإلا…»: التهديد الذي لا ينفّذه أحد', 'رسالة تعدك بالحظ إن أرسلتها، وبالكوارث إن حذفتها، والنتيجة صفر في الحالتين', 'تصلك رسالة تبدأ بجملة مرعبة: «لا تتجاهلها! أرسلها لعشرة أشخاص خلال ساعة، وسيحدث لك خيرٌ عظيم، ومن يحذفها فسيندم». وفجأة تجد نفسك أمام معادلة كونية خطيرة يقودها زرّ «إعادة توجيه».

المنطق فيها عبقري في سذاجته: مستقبلك كله معلّق على عشر رسائل. أرسلها فتصبح محظوظًا ثريًا سعيدًا، واحذفها فتنهار حياتك. وكأن الكون ينتظر إحصائية إرسالك ليقرر مصيرك، وهو أضعف نظام قدري يمكن تخيّله.

والطريف أن ملايين البشر حذفوا هذه الرسائل منذ سنوات وما زالوا بخير، بينما آخرون أرسلوها بإخلاص ولم يتغيّر شيء، لأن الحظ والرزق لا يوزّعان بعدد الرسائل المُعاد توجيهها.

ومع ذلك تنتشر لأنها تلعب على وترٍ واحد: «وماذا لو كانت صحيحة؟». هذا التردّد الصغير هو وقودها، وهو نفسه ما يجعلنا نضغط الزر ونحن نضحك على أنفسنا.

الحكم: هزلٌ صريح للترفيه. لا رسالة تجلب حظًا، ولا حذفها يجلب شؤمًا، والزر الوحيد المناسب لمثل هذه السلاسل هو «حذف» بضمير مرتاح. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['إشاعات','واتساب','سخرية']::text[]),
  ('cumin-lemon-diet', 'رجيم الكمّون والليمون: يذيب الدهون ويذيب معها المنطق', 'مشروبٌ واحد يعدك بخصرٍ نحيل من دون رياضة ولا حِمية ولا حتى تعب', 'كل موسمٍ يطلّ علينا مشروب سحري جديد يَعِدُ بإذابة الدهون وأنت نائم: مرة كمّون بليمون، ومرة قرفة بعسل، ومرة خليط غامض من كل ما في المطبخ. الوعد ثابت دائمًا: «اشربه على الريق وشوف الفرق»، أما الفرق الوحيد المؤكد فهو في طعم فمك صباحًا.

الفكرة مغرية لأنها تبيع الحلم الأسهل: خسارة الوزن بلا رياضة ولا تقليل أكل ولا صبر، فقط كوب واحد كل صباح. ولو كان الأمر بهذه البساطة لأغلقت النوادي الرياضية أبوابها واكتفى العالم بأكياس الكمّون.

طبعًا الكمّون والليمون مكوّنات لذيذة وتضيف نكهة جميلة للطعام، وهذا شيءٌ طيّب. لكن تحويلهما إلى «حارقٍ للدهون» يتجاهل الحقيقة المملّة الوحيدة التي لا تتغير: الوزن مسألة توازنٍ بين ما يدخل الجسم وما يصرفه، لا مسألة مشروبٍ يعمل بالسحر.

وحين لا ينزل الوزن، يأتي العذر الجاهز: «أكيد ما ضبطت المقادير»، فيُلقى اللوم على الملعقة لا على الوصفة، وتستمر الحلقة إلى موسم المشروب المعجزة القادم.

الحكم: مكتوب بروح ساخرة للتسلية. لا مشروب يذيب الدهون وحده؛ الطعام المتوازن والحركة والصبر هي «الوصفة» الوحيدة المملّة والصحيحة معًا. اشرب الكمّون لأنه لذيذ، لا لأنه سيصنع لك خصرًا. مقياس الخزعبلة: 5 من 5.', 'satire', 5, 'draft', ARRAY['رجيم','مبالغات','سخرية']::text[]),
  ('japan-number-4', 'لماذا يختفي الطابق رقم 4 من مصاعد اليابان؟', 'في اليابان قد تدخل المصعد فلا تجد زرًّا للطابق الرابع… فأين اختفى؟', 'في كثير من المستشفيات والفنادق اليابانية تصعد المصعد فتقفز الأرقام من 3 إلى 5، وتبحث عن الغرفة رقم 4 فلا تجدها. السبب لغوي بحت: كلمة «أربعة» في اليابانية تُنطق «شي»، وهي النطق نفسه لكلمة «الموت» (死). ومن هنا وُلد ما يسميه العلماء «رهاب الرقم أربعة».

ولأن الأذن اليابانية تربط الرقم بالموت لا شعوريًّا، تجنّبته الحياة اليومية: الهدايا لا تُقدَّم في مجموعات من أربع قطع، وبعض شركات الأجهزة تتخطى الرقم في تسلسل منتجاتها. ويُضاف إليه أحيانًا الرقم 9 لأن نطقه «كو» يشبه كلمة تعني «المعاناة».

والطريف أن هذا الرهاب ليس يابانيًّا خالصًا؛ فهو منتشر في الصين وكوريا أيضًا لأسباب لغوية مشابهة، حتى إن بعض المباني هناك تحذف أرقام الطوابق التي تحوي أربعة كلها. إنه مثال جميل على كيف تصنع مصادفة صوتية بين كلمتين خرافةً تمتد عبر قارة كاملة.

الحكم: الرقم 4 لا يقتل أحدًا، لكن ظاهرة تجنّبه حقيقية وواسعة الانتشار. مصادفة لغوية بريئة تحولت إلى عادة ثقافية راسخة. مستوى الخزعبلة: 3 من 5.', 'world', 3, 'draft', ARRAY['اليابان','أرقام','خرافة لغوية']::text[]),
  ('black-cat-luck', 'القط الأسود: نذير شؤم أم حامل حظ؟', 'القط نفسه يجلب النحس في بلد والسعد في آخر… فمن الصادق؟', 'قلّ أن يوجد حيوان اختلف الناس في سمعته مثل القط الأسود. ففي أوروبا في العصور الوسطى ارتبط في الأذهان بالسحر والساحرات، حتى صار مرور قط أسود من أمامك علامة تشاؤم تلتصق بالثقافة الغربية إلى اليوم.

لكن انتقل بضعة كيلومترات فتنقلب الصورة رأسًا على عقب. ففي بريطانيا وأيرلندا يُعدّ مرور القط الأسود من أمامك فألًا حسنًا، وكانت زوجات البحّارة يحتفظن بقط أسود في البيت أملًا في عودة الأزواج سالمين. وفي اليابان يُنظر إليه على أنه جالب للحظ، خصوصًا للفتيات العازبات.

هذا التناقض وحده كافٍ لكشف الحقيقة: لو كان لِلون القط تأثير فعلي في الحظ لكان تأثيره واحدًا في كل مكان، لا سعدًا هنا ونحسًا هناك. التفسير الحقيقي أن اللون الأسود ارتبط تاريخيًّا بالظلام والغموض، فحمّلته كل ثقافة معنى من عندها.

أما ضحية القصة الحقيقية فهي القطط السوداء نفسها؛ إذ لا تزال بعض ملاجئ الحيوانات تشكو أنها الأبطأ في التبنّي بسبب سمعة لا ذنب لها فيها.

الحكم: لون فرو القط لا علاقة له بحظك إطلاقًا، والدليل أن العالم اختلف في تفسيره. خرافة صريحة لطيفة الضحية. مستوى الخزعبلة: 4 من 5.', 'world', 4, 'draft', ARRAY['قطط','حظ','تشاؤم']::text[]),
  ('broken-mirror-seven-years-2', 'كسرت مرآة؟ استعدّ لسبع سنوات من النحس!', 'من أين جاء رقم السبعة بالتحديد؟ الحكاية أقدم مما تتخيّل.', '«من كسر مرآة نالته سبع سنوات من النحس»؛ عبارة تسمعها في أفلام كثيرة ويرددها الناس نصف جادّين. لكن من أين جاءت، ولماذا سبعٌ لا خمسٌ ولا عشر؟

يعود جذر الخرافة إلى الرومان القدماء، الذين اعتقدوا أن المرآة لا تعكس الوجه فحسب بل تحمل جزءًا من روح صاحبها. فإذا انكسرت، انكسرت معها الروح وتشوّهت، ثم تحتاج إلى سبع سنوات كي تتجدد وتتعافى، لأنهم كانوا يظنون أن جسد الإنسان يتجدد كليًّا كل سبع سنوات.

ويُضاف إلى ذلك سبب مادي بسيط: كانت المرايا في القِدم باهظة الثمن وناعمة الصنع، فكسرها خسارة حقيقية موجعة للجيب. فما أسهل أن يُلبَس هذا الأسف الاقتصادي ثوبًا خرافيًّا مخيفًا ليردع الناس عن الإهمال.

الحكم: لا شظية زجاج تملك مفتاح سبع سنوات من حياتك، والرقم مجرد بقايا معتقد روماني عن تجدد الجسد. خرافة كبرى بامتياز، وإن كان جمع الزجاج المكسور بحذر فكرة حكيمة فعلًا. مستوى الخزعبلة: 5 من 5.', 'world', 5, 'draft', ARRAY['مرايا','الرومان','نحس']::text[]),
  ('salt-over-shoulder', 'لماذا يرمي الغربيون الملح فوق أكتافهم؟', 'انسكب الملح على المائدة فقفز الجميع لرمي حفنة خلف ظهورهم… لماذا؟', 'في كثير من الموائد الغربية، إذا انسكب الملح ترى أحدهم يلتقط قليلًا منه ويقذفه فوق كتفه الأيسر. مشهد طريف وراءه معتقد قديم يقول إن سكب الملح يجلب سوء الطالع، وإن رمي حفنة فوق الكتف الأيسر يصيب الشيطان — الذي يُظنّ أنه يتربص خلف كتفك اليسرى — في عينيه فيطرده.

ولكي تفهم قدسية الملح في وعي القدماء تذكّر أنه كان سلعة نفيسة وأداة حفظ للطعام لا غنى عنها. حتى إن كلمة «راتب» في الإنجليزية (salary) تعود في أصلها اللاتيني إلى كلمة «الملح». فإهدار مادة بهذه القيمة كان يُنظر إليه بوصفه فألًا سيئًا يستحق «إصلاحًا».

وقد رسّخت الفنون هذه الصورة؛ ففي لوحة العشاء الأخير لليوناردو دافنشي يظهر ملح مقلوب قرب يهوذا، فربطها الناس بالخيانة وسوء الحظ.

الحكم: الملح المنسكب لا يستدعي شياطين ولا يفسد يومك، لكن الطقس بقايا زمن كان الملح فيه ثروة. خرافة ظريفة لا ضرر منها سوى قليل من الفوضى على المائدة. مستوى الخزعبلة: 4 من 5.', 'world', 4, 'draft', ARRAY['ملح','طقوس','تشاؤم']::text[]),
  ('friday-13th-fear', 'الجمعة والثالث عشر: أخطر يوم في التقويم الغربي؟', 'طوابق تُحذف وصفوف طائرات تختفي… كل ذلك خوفًا من رقم واحد.', 'الرقم 13 هو نجم الرعب في الثقافة الغربية، والخوف منه شائع إلى حدّ أن له اسمًا علميًّا: «تريسكايديكافوبيا». وكثير من الفنادق والمباني تتخطى الطابق الثالث عشر، وبعض شركات الطيران تحذف صف المقاعد رقم 13، وكأن حذف الرقم يحذف معه الخطر.

تتعدد التفسيرات لأصل هذه السمعة. أشهرها أن العشاء الأخير جمع ثلاثة عشر شخصًا على المائدة، الثالث عشر منهم كان الخائن. وثمة رواية من الأساطير الإسكندنافية عن وليمة حضرها إله الشرّ «لوكي» ضيفًا ثالث عشر غير مدعوّ فجلب الكارثة.

فإذا اجتمع الرقم 13 مع يوم الجمعة اشتدّ التشاؤم عند كثيرين، حتى صار «الجمعة الثالث عشر» مضربًا للأمثال وعنوانًا لأفلام رعب. ومع ذلك، لا تُظهر الإحصاءات أي زيادة حقيقية في الحوادث في ذلك اليوم مقارنة بغيره.

الحكم: الرقم 13 رقم كأي رقم، والخوف منه إرث ثقافي وديني متراكم لا سند له في الواقع. خرافة راسخة لكنها بلا أنياب. مستوى الخزعبلة: 4 من 5.', 'world', 4, 'draft', ARRAY['الرقم 13','الجمعة','رهاب']::text[]),
  ('knock-on-wood', 'لماذا يطرق الغربيون على الخشب عند ذكر أمنية؟', '«ما شاء الله» لها مقابل غربي… لكنه يُقرَع على طاولة خشبية.', 'حين يتحدث أحدهم في الغرب عن نعمة يخشى زوالها — كصحة أو نجاح — تراه يمدّ يده ويطرق على أقرب سطح خشبي وهو يقول «touch wood» أو «knock on wood». إنه تعويذة صغيرة لطرد الحسد وحماية النعمة من أن «تُنطق فتنقلب».

يرجّح كثيرون أن أصل العادة يعود إلى معتقدات وثنية قديمة كانت ترى في الأشجار مساكن لأرواح أو آلهة، فكان لمس الخشب استنجادًا بتلك الأرواح أو شكرًا لها. وفسّرها آخرون بربطها بخشب الصليب في التقليد المسيحي، طلبًا للحماية والبركة.

والجميل أن لكل ثقافة نسختها من الفكرة نفسها: تعبير عن الامتنان مع خشية خفية من أن الحديث عن الخير قد يستدعي نقيضه. إنها حاجة إنسانية عابرة للحدود أكثر منها قاعدة كونية.

الحكم: قرع الخشب لا يحمي نعمة ولا يدفع حسدًا، لكنه تعبير إنساني قديم عن الشكر والقلق معًا. خرافة أليفة لا أذى فيها. مستوى الخزعبلة: 4 من 5.', 'world', 4, 'draft', ARRAY['الخشب','حظ','تقاليد']::text[]),
  ('la-tomatina-spain', 'بلدة إسبانية تتحول شوارعها إلى بحر من الطماطم!', 'مرة كل عام يخوض عشرات الآلاف أكبر معركة طعام في التاريخ.', 'في بلدة «بونيول» الصغيرة قرب مدينة فالنسيا الإسبانية، يتحول آخر أربعاء من أغسطس إلى مشهد لا يُصدَّق: شوارع تغرق في نهر أحمر من الطماطم، وعشرات الآلاف من الناس يتقاذفونها بضحك وصخب في مهرجان اسمه «لا توماتينا».

بدأ التقليد عام 1945 على نحو عفوي، إذ تقول الروايات إن مشادّة بين شبان قرب سوق للخضار انتهت بتراشق بالطماطم، فأعجبت اللعبة الجميع حتى صارت موعدًا سنويًّا ثابتًا. واليوم تُجلب مئات الأطنان من الطماطم شديدة النضج خصيصًا لهذا اليوم.

وللمعركة قواعد لطيفة: يجب هرس الطماطم باليد قبل رميها كي لا تؤذي أحدًا، ويُطلَق نشاط المعركة وينتهي بإشارة محددة. وبسبب ضخامة الإقبال صار الدخول اليوم بتذاكر لعدد محدود من المشاركين.

الحكم: هذا ليس خرافة أصلًا، بل احتفال حقيقي مرِح لا يزعم أنه يجلب حظًّا أو يدفع شرًّا. غرابة ممتعة صادقة مع نفسها. مستوى الخزعبلة: 2 من 5.', 'world', 2, 'draft', ARRAY['إسبانيا','مهرجانات','طماطم']::text[]),
  ('horseshoe-luck', 'حدوة الحصان فوق الباب: للزينة أم للحظ؟', 'قطعة حديد صدئة علّقها الأوروبيون فوق أبوابهم قرونًا… لماذا؟', 'تعليق حدوة حصان فوق باب المنزل عادة قديمة في أوروبا وأمريكا، يُعتقد أنها تجلب الحظ وتحمي البيت من الشرّ. ووراءها سببان تصوّرهما القدماء: الحديد نفسه كان يُظنّ أنه يطرد الأرواح الخبيثة والجنّ، وشكل الحدوة الهلالي رمز للبركة.

وتنسج حول أصلها حكاية شعبية طريفة عن القديس دَنستان الذي كان حدّادًا، يُروى أنه أمسك بالشيطان وثبّت حدوة مؤلمة في حافره، ولم يطلقه إلا بعد أن وعده ألا يدخل بيتًا معلّقة على بابه حدوة. قصة رمزية بالطبع، لكنها تشرح لماذا صارت الحدوة تميمة حماية.

وهنا يختلف الناس حتى اليوم: هل تُعلَّق بفتحتها إلى الأعلى كي «تحفظ الحظ» فلا يتسرب، أم إلى الأسفل كي «يُسكَب الحظ» على الداخلين؟ ولكل فريق حجته، وهو خلاف يكشف أن القاعدة من صنع الخيال لا الواقع.

الحكم: قطعة الحديد لا تجلب حظًّا ولا تصدّ شرًّا، والاختلاف في طريقة تعليقها أوضح دليل على ذلك. خرافة عريقة لكنها زينة لطيفة لا أكثر. مستوى الخزعبلة: 4 من 5.', 'world', 4, 'draft', ARRAY['حدوة الحصان','حظ','تمائم']::text[]),
  ('walking-under-ladder', 'لماذا يتجنّب الغربيون المرور تحت السلّم؟', 'خرافة قديمة تختبئ خلفها نصيحة سلامة صادقة جدًّا.', 'من العادات المتجذّرة في الغرب تجنّب المرور تحت سلّم مسنود إلى جدار، خوفًا من أن يجلب ذلك سوء الحظ. وللفكرة تفسير رمزي قديم: السلّم مع الجدار والأرض يكوّن مثلثًا، والمثلث في التقاليد المسيحية رمز للثالوث المقدس أو للحياة، فالمرور عبره «كسرٌ» له يجلب النحس.

لكن خلف الغلاف الخرافي تختبئ حكمة عملية حقيقية. فالمرور تحت سلّم قائم خطر فعلًا؛ قد تسقط عليك أداة أو دلو طلاء، أو تصطدم بالسلّم فتُوقع من يقف عليه. أي أن الخرافة هنا تغلّف نصيحة سلامة سليمة بثوب مخيف كي يلتزم بها الناس.

وهذا نمط متكرر في كثير من المعتقدات الشعبية: تأخذ سلوكًا حكيمًا وتلبسه قصة عن الحظ لتضمن أن يتوارثه الجميع دون نقاش.

الحكم: لا قوى خفية تعاقب من يمرّ تحت السلّم، لكن الابتعاد عنه فكرة سليمة لسبب مادي بسيط. خرافة ذات نواة عملية صادقة. مستوى الخزعبلة: 3 من 5.', 'world', 3, 'draft', ARRAY['سلامة','خرافة','حظ']::text[]),
  ('trevi-fountain-coins', 'لماذا يرمي ملايين السياح عملاتهم في نافورة روما؟', 'عملة واحدة فوق الكتف تَعِدُك بالعودة إلى روما… والباقي للفقراء.', 'أمام نافورة «تريفي» الباروكية الشهيرة في روما، يقف السياح كل يوم صفوفًا، يديرون ظهورهم للماء ويقذفون عملة فوق الكتف الأيسر باليد اليمنى. التقليد يقول: عملة واحدة تضمن لك العودة إلى روما يومًا ما، وثانية تجلب قصة حب، وثالثة تعِد بزواج.

هذا الطقس رومانسي بلا شك، لكن ما يجعله لافتًا حقًّا هو أثره الواقعي. فمجموع ما يُرمى في النافورة يبلغ نحو مليون ونصف المليون يورو سنويًّا، تُجمَع بانتظام وتُخصَّص لأعمال خيرية تساعد المحتاجين في المدينة. أما التقاط العملات من النافورة فممنوع قانونًا.

وهكذا تجتمع في مشهد واحد أسطورة لطيفة عن «العودة إلى روما» وحقيقة نافعة عن مساعدة الفقراء؛ فالعملة لا تعيدك فعلًا، لكنها قد تُطعم جائعًا.

الحكم: رمي العملة لن يعيدك إلى روما بقدرة سحرية، غير أن التقليد حقيقي ونبيل الأثر لأنه يموّل الخير. أسطورة جميلة بنهاية سعيدة. مستوى الخزعبلة: 3 من 5.', 'world', 3, 'draft', ARRAY['روما','نوافير','طقوس سفر']::text[])
on conflict (slug) do nothing;
